#!/bin/bash
set -eo pipefail
umask 077
export CUDA_VISIBLE_DEVICES='' PYTHONDONTWRITEBYTECODE=1
exec timeout --signal=TERM --kill-after=5s 180s /data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -B - <<'PY_OWN_TAIL_DEPLOY'
import base64,hashlib,io,json,os,pathlib,re,subprocess,sys,time,traceback,zipfile
assert not os.environ.get('SLURM_JOB_ID') and os.environ.get('CUDA_VISIBLE_DEVICES')==''
root=pathlib.Path('/data1/home/sunyiq/china_input_completion_hpc_20261015_001/hydroatlas_login_tail_compute_parse_v1')
assert root.parent.resolve(strict=True)==root.parent and not root.exists()
root.mkdir(mode=0o700);(root/'logs').mkdir(mode=0o700)
def save(name,value):
 raw=(json.dumps(value,ensure_ascii=False,indent=2)+'\n').encode();assert len(raw)<=65536
 with (root/name).open('xb') as stream:stream.write(raw)
save('DEPLOYMENT_STARTED.json',dict(source_gets_max=2,old_failure_job='243539',automatic_retries=0))
packed=base64.b64decode('',validate=True)
assert len(packed)==97517 and hashlib.sha256(packed).hexdigest()=='24d44d400547fd69b5ba098647b7c9fee388b99ae26197c0501c7e4170c4341a'
expected={'acquire_hydroatlas_tail_login_v1.py': {'bytes': 6503, 'sha256': '22b796c1c75771726bbf84cbdfb8b44ecc2df3f1b5bebbc85f9c417884568bc2'}, 'parse_hydroatlas_saved_tail_v1.py': {'bytes': 7234, 'sha256': '7ecf9f2164aac9677a2f79135cc3b737c5460d44f23fff4ad3b6e9e931ca934b'}, 'tail_login_control_v2.py': {'bytes': 1704, 'sha256': 'c803ed1f56789f67fea6f81d9d995b5c28523e7a94027f5ba3bf50a64a7d7e33'}, 'tail_compute_control_v2.py': {'bytes': 2724, 'sha256': '6a937a69ef2c92af7e1ef2558788afbc1a93dfcd492c5afabf3a516770bffd2e'}, 'tail_owned_stage_control_v2.py': {'bytes': 6046, 'sha256': 'ec3da0f7f94ab92dde3c663be2a5a5c993f168dea06810d12929a02f30ce8728'}, 'inspect_common_source_presence_v2.py': {'bytes': 5138, 'sha256': 'eeb74c9d601412199f89f282e3734072e53f6c1df60e28529758cbd802ab8c31'}, 'hydroatlas_pinned_transport_v1.py': {'bytes': 3325, 'sha256': '8ef3a4e49e2a58e5f223f67640994f295dbea659088417553df467e6d50b25ee'}, 'TAIL_CONTRACT.json': {'bytes': 1373, 'sha256': 'e3070acd66ffab461ed05242321a67225a0c784e3bdc35721a32fc591ef87b87'}, 'COMMON_PRESENCE_CONTRACT.json': {'bytes': 514, 'sha256': '7414ba8291313665b45b8ce86224676733d381e9d06f2ee4bf1bff1d097862fb'}, 'COMMON_HPC_PRESENCE_DRAFT_v2.json': {'bytes': 834137, 'sha256': '57451b019b12c5c7fcda233dec4a5135a2ea171bdf4391f401efb2a84761a805'}, 'DNS_RESOLUTION.json': {'bytes': 2796, 'sha256': 'f7419025eb61385d3f2680c02d01aa283cf25257eab888fffc7a69d400961f0f'}, 'parse.sbatch': {'bytes': 889, 'sha256': '19164fcd8242919596d86b306be6951a505fbe60e59c363b21c9d648138d9b92'}, 'ENTRY_TABLE.json': {'bytes': 1687, 'sha256': 'ca436ead8255804384cca9275f25eba35bbb119b37b716c1f59c54923addd30e'}}
with zipfile.ZipFile(io.BytesIO(packed)) as archive:
 names=archive.namelist();assert len(names)==len(set(names))==13 and set(names)==set(expected)
 assert sum(item.file_size for item in archive.infolist())<=1048576
 for name in names:
  assert pathlib.Path(name).name==name and name not in ('','.','..')
  info=archive.getinfo(name);descriptor=expected[name]
  assert not info.is_dir() and not info.flag_bits&1 and info.file_size==descriptor['bytes']
  raw=archive.read(name);assert len(raw)==descriptor['bytes'] and hashlib.sha256(raw).hexdigest()==descriptor['sha256']
  with (root/name).open('xb') as stream:stream.write(raw)
print('OWN_ATLAS_DIRECTORY_PAYLOAD_VERIFIED=13',flush=True)
sys.path.insert(0,str(root))
control_returned_normally=False
try:
 import tail_login_control_v2 as control
 control.main()
 control_returned_normally=True
except BaseException as error:
 if not (root/'LOGIN_CONTROL_FAILURE.json').exists():
  save('LOGIN_CONTROL_FAILURE.json',dict(error_type=type(error).__name__,error=str(error),traceback=traceback.format_exc()[-8192:]))
 if not isinstance(error,Exception):raise
accepted=False
if (control_returned_normally and not (root/'LOGIN_CONTROL_FAILURE.json').exists()
 and not (root/'TAIL_FAILURE.json').exists() and (root/'LOGIN_CONTROL_RESULT.json').exists()):
 value=json.loads((root/'LOGIN_CONTROL_RESULT.json').read_bytes());accepted=value['accepted'] is True
if not accepted:
 save('SUBMISSION_RESULT.json',dict(status='SOURCE_TRANSPORT_FAILED_NO_JOB',job_id='NONE',new_slurm_jobs=0))
 print('OWN_ATLAS_DIRECTORY_JOB_ID=NONE',flush=True)
 print('OWN_ATLAS_TAIL_TRANSPORT_FAILED_NO_JOB=1',flush=True)
 print('OWN_ATLAS_DIRECTORY_SUBMIT_DONE',flush=True)
else:
 save('SUBMISSION_STARTED.json',dict(command=['sbatch','parse.sbatch'],automatic_retries=0))
 try:
  result=subprocess.run(['sbatch','parse.sbatch'],cwd=root,capture_output=True,timeout=25)
 except BaseException as error:
  save('SUBMISSION_RESULT.json',dict(status='SUBMISSION_UNCONFIRMED',job_id=None,error_type=type(error).__name__,error=str(error)))
  raise
 assert len(result.stdout)<=65536 and len(result.stderr)<=65536
 match=re.fullmatch(rb'Submitted batch job ([0-9]+)\n',result.stdout)
 if result.returncode!=0 or match is None:
  save('SUBMISSION_RESULT.json',dict(status='SUBMISSION_UNCONFIRMED',job_id=None,exit_code=result.returncode,
   stdout=result.stdout.decode('utf8',errors='replace'),stderr=result.stderr.decode('utf8',errors='replace')))
  raise RuntimeError('OWN_SUBMISSION_NOT_CONFIRMED_NEVER_REPLAY')
 job=match[1].decode()
 with (root/'OWN_ATLAS_DIRECTORY_JOB_ID').open('xb') as stream:stream.write((job+'\n').encode())
 save('SUBMISSION_RESULT.json',dict(status='UNIQUE_JOB_SUBMITTED',job_id=job,exit_code=result.returncode,
  stdout=result.stdout.decode(),stderr=result.stderr.decode('utf8',errors='replace')))
 print(result.stdout.decode(),end='',flush=True)
 print('OWN_ATLAS_DIRECTORY_JOB_ID='+job,flush=True)
 print('OWN_ATLAS_DIRECTORY_SUBMIT_DONE',flush=True)
PY_OWN_TAIL_DEPLOY
